export class QuotaExceededError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'QuotaExceededError';
    this.code = code;
  }
}

// Internal state of every gate, shared with child gates through a WeakMap so
// the public gate object keeps its exact shape.
const gateState = new WeakMap();

// Monotonic counter that never repeats or moves backwards, independent of the
// (mocked, possibly frozen) wall clock; gives queued entries a global arrival
// order so reparented queues can merge fairly.
let enqueueSeq = 0;

function assertInteger(value, name) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new TypeError(`${name} must be an integer`);
  }
}

function assertSignal(signal) {
  if (
    signal !== undefined &&
    signal !== null &&
    (typeof signal !== 'object' ||
      typeof signal.addEventListener !== 'function' ||
      typeof signal.removeEventListener !== 'function')
  ) {
    throw new TypeError('signal must be an AbortSignal');
  }
}

export function createGate({ limit, windowMs, maxWaitMs = 0, parent } = {}) {
  assertInteger(limit, 'limit');
  assertInteger(windowMs, 'windowMs');
  assertInteger(maxWaitMs, 'maxWaitMs');
  if (limit <= 0) throw new RangeError('limit must be a positive integer');
  if (windowMs <= 0) throw new RangeError('windowMs must be a positive integer');
  if (maxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');

  let parentState = null;
  if (parent !== undefined && parent !== null) {
    parentState = gateState.get(parent);
    if (parentState === undefined) {
      throw new TypeError('parent must be a gate created by createGate');
    }
    if (limit > parentState.limit) {
      throw new RangeError('limit must not exceed parent limit');
    }
  }

  const state = {
    limit,
    windowMs,
    maxWaitMs,
    parent: parentState,
    children: new Set(),
    isRoot: parentState === null,
    // Own-window accounting.
    ownGen: 0, // bumped on every own-window flip, invalidates old handles
    usedOwn: 0, // own units granted/lent in this gate's current own window
    inFlight: 0, // units occupied through this gate and not yet cleared
    borrowedInFlight: 0, // units this gate's own occupations borrowed; reclaimed at lender flips
    lentInFlight: 0, // own units lent to descendants' admitted occupations
    borrowedInFlightReserved: 0, // (unused legacy alias slot, kept intentionally absent)
    poolDraw: 0, // units charged into the current window of the root pool
    // Reservation accounting (cross-gate acquireAll).
    reserved: 0, // stat: units currently held by uncommitted reservations on this gate
    rolledBack: 0, // stat: failed reservation attempts owned by this gate
    pendingOwn: 0, // own-window units reserved for queued combos where this gate is a member
    pendingLends: 0, // own-window units this gate lends to queued combos
    resvAsMember: null, // entries holding this gate's own quota as a member (Set)
    resvAsLender: null, // entries holding this gate's own quota as a lender (Set)
    lentLinks: null, // admitted occupation links lent from this gate (Set of link)
    // Observability.
    waiting: 0, // units currently queued through this gate
    granted: 0,
    refused: 0,
    expired: 0,
    cancelled: 0,
    openHandles: new Set(),
    root: null,
    timer: null,
  };
  delete state.borrowedInFlightReserved;
  state.resvAsMember = new Set();
  state.resvAsLender = new Set();
  state.lentLinks = new Set();

  let root;
  if (parentState === null) {
    root = state;
    // The quota pool shared by the whole hierarchy lives on the root gate.
    Object.assign(state, {
      poolLimit: limit,
      poolGen: 0, // bumped on every root-window flip
      poolUsed: 0, // units granted/reserved through every gate in the current pool window
      poolLinks: new Set(), // admitted occupation links drawn from the root pool
      poolResv: new Set(), // queued entries holding pool units / root own units
      queue: [], // queued requests from every gate, in arrival order
      head: 0, // index of the first live entry; entries are never shifted
      liveQueued: 0, // entries not yet settled
      lendGates: new Set(), // non-root gates currently lending own quota to queued combos
      minDeadline: Infinity, // earliest live deadline, skips idle sweeps
      lastNow: 0, // monotonic clock: never moves backwards
      members: new Set(),
    });
    state.members.add(state);
  } else {
    root = parentState.root;
    root.members.add(state);
    parentState.children.add(state);
  }
  state.root = root;

  // Operational helpers read state.root dynamically rather than capturing the
  // local `root`: reparent() can move this gate (and its descendants) into
  // another family's pool.
  function now() {
    const r = state.root;
    const t = Date.now();
    if (t > r.lastNow) r.lastNow = t;
    return r.lastNow;
  }

  // Own-window units this gate can still commit or promise. The root's own
  // window IS the pool window, so its headroom is pool headroom.
  function ownAvail(g, r) {
    if (g === r) return r.poolLimit - r.poolUsed;
    return Math.max(0, g.limit - g.usedOwn - g.pendingOwn - g.pendingLends);
  }

  // --- Reservation gathering ------------------------------------------------
  //
  // A gather walks every member: first the member's own current-window quota,
  // then its direct parent, then up the chain. Each non-root link consumes that
  // ancestor's own-window slice; every gathered unit draws the root pool. Every
  // step is O(members * chain depth) and uses intrusive sets, so commit and
  // rollback never scan the queue or the family.

  function makeSegs(memberGates, unitOf) {
    const segs = [];
    for (const gate of memberGates) {
      segs.push({ gate, units: unitOf(gate), own: 0, links: [] });
    }
    return segs;
  }

  // Mutates counters while gathering; returns true on full success. On failure
  // the caller invokes releaseGather to undo every mutation.
  function gather(segs) {
    const r = state.root;
    for (const seg of segs) {
      const m = seg.gate;
      let take = Math.min(seg.units, ownAvail(m, r));
      seg.own = take;
      r.poolUsed += take;
      m.pendingOwn += take;
      m.reserved += take;
      m.resvAsMember.add(null); // (removed below; placeholder to keep shape obvious)
      m.resvAsMember.delete(null);
      let need = seg.units - take;
      let cur = m.parent;
      while (need > 0) {
        if (cur === null) return false;
        const isPool = cur === r;
        const avail = isPool ? r.poolLimit - r.poolUsed : ownAvail(cur, r);
        take = Math.min(need, Math.max(0, avail));
        if (take > 0) {
          r.poolUsed += take;
          const link = {
            kind: isPool ? 'pool' : 'own',
            lender: cur,
            units: take,
            released: false,
            entry: null,
          };
          seg.links.push(link);
          if (isPool) {
            // Pool headroom is the hard stop; if even the pool cannot cover
            // the remaining units this gather can never complete.
            if (take < need) return false;
            need = 0;
          } else {
            cur.pendingLends += take;
            cur.reserved += take;
            need -= take;
          }
        }
        cur = cur.parent;
      }
    }
    return true;
  }

  // Register which queued entry owns each gathered link / member claim, and
  // wire the intrusive sets used by window flips. Done after a successful
  // gather so a rolled-back attempt leaves no sets behind.
  function bindGather(entry, segs) {
    const r = state.root;
    for (const seg of segs) {
      const m = seg.gate;
      m.resvAsMember.add(entry);
      for (const link of seg.links) {
        link.entry = entry;
        if (link.kind === 'pool') {
          r.poolResv.add(entry);
        } else {
          const g = link.lender;
          if (!g.resvAsLender.has(entry)) {
            g.resvAsLender.add(entry);
            r.lendGates.add(g);
          }
        }
      }
    }
  }

  // Undo gather() mutations. Individual links may already have been released
  // by a lender window flip (link.released); those are skipped.
  function releaseGather(entry, segs) {
    const r = state.root;
    for (const seg of segs) {
      const m = seg.gate;
      if (!seg.ownReleased) {
        r.poolUsed -= seg.own;
        m.pendingOwn -= seg.own;
        m.reserved -= seg.own;
        seg.ownReleased = true;
      }
      m.resvAsMember.delete(entry);
      for (const link of seg.links) {
        if (link.released) continue;
        link.released = true;
        r.poolUsed -= link.units;
        if (link.kind === 'own') {
          const g = link.lender;
          g.pendingLends -= link.units;
          g.reserved -= link.units;
          g.resvAsLender.delete(entry);
          if (g.resvAsLender.size === 0) r.lendGates.delete(g);
        } else {
          r.poolResv.delete(entry);
        }
      }
    }
  }

  // Forget a gather after its pool-side reservation was reclaimed by a root
  // window flip: poolUsed bookkeeping for those links is gone with the reset.
  function detachGather(entry, segs, { ownOnly }) {
    const r = state.root;
    for (const seg of segs) {
      const m = seg.gate;
      if (ownOnly) {
        // Member-own claims survive unless the member itself is the flipping
        // root; the caller filters before invoking.
      }
      m.resvAsMember.delete(entry);
      for (const link of seg.links) {
        if (link.released) continue;
        if (link.kind === 'pool') {
          link.released = true;
          r.poolResv.delete(entry);
        }
      }
    }
  }

  // --- Commit: reservations become admitted occupations ---------------------

  function commit(entry, segs) {
    const r = state.root;
    const committedSegs = [];
    const handleRecords = [];
    for (const seg of segs) {
      const m = seg.gate;
      r.poolUsed -= seg.own; // pending claim becomes an occupation inside the SAME pool window
      m.pendingOwn -= seg.own;
      m.reserved -= seg.own;
      m.resvAsMember.delete(entry);
      m.usedOwn += seg.own;
      m.inFlight += seg.units;
      m.poolDraw += seg.units;
      const committedLinks = [];
      let borrowed = 0;
      for (const link of seg.links) {
        r.poolUsed -= link.units;
        const cl = {
          kind: link.kind,
          lender: link.lender,
          member: m,
          units: link.units,
          gen: link.kind === 'pool' ? r.poolGen : link.lender.ownGen,
        };
        borrowed += link.units;
        committedLinks.push(cl);
        if (link.kind === 'pool') {
          r.poolLinks.add(cl);
          r.poolResv.delete(entry);
        } else {
          const g = link.lender;
          g.pendingLends -= link.units;
          g.reserved -= link.units;
          g.resvAsLender.delete(entry);
          if (g.resvAsLender.size === 0) r.lendGates.delete(g);
          g.usedOwn += link.units;
          g.inFlight += link.units;
          g.lentInFlight += link.units;
          g.lentLinks.add(cl);
        }
      }
      m.borrowedInFlight += borrowed;
      // Re-charge the whole occupation to the pool in its committed form. The
      // subtract/add pair nets to zero: gathered units already drew pool room,
      // and the commit keeps drawing exactly that room.
      r.poolUsed += seg.units;
      const cseg = {
        member: m,
        own: seg.own,
        ownGen: m.ownGen,
        links: committedLinks,
      };
      committedSegs.push(cseg);
      const rec = { seg: cseg };
      handleRecords.push(rec);
      m.openHandles.add(rec);
    }
    return makeComboHandle(handleRecords);
  }

  // The public handle exposes exactly one own closure property: release. It
  // closes over its segment records, so destructuring it (`const { release } =
  // await ...; release()`) needs no receiver.
  function makeComboHandle(records) {
    let active = true;
    const handle = {
      release() {
        if (!active) return;
        active = false;
        const r = state.root;
        for (const rec of records) {
          const { seg } = rec;
          const m = seg.member;
          m.openHandles.delete(rec);
          if (seg.own > 0 && seg.ownGen === m.ownGen) {
            m.inFlight -= seg.own;
          }
          for (const link of seg.links) {
            const live = link.kind === 'pool'
              ? link.gen === r.poolGen
              : link.gen === link.lender.ownGen;
            if (!live) continue; // window already reclaimed this side
            if (link.kind === 'pool') {
              r.poolLinks.delete(link);
            } else {
              link.lender.lentLinks.delete(link);
              link.lender.inFlight -= link.units;
              link.lender.lentInFlight -= link.units;
            }
            m.inFlight -= link.units;
            m.borrowedInFlight -= link.units;
          }
        }
      },
    };
    return handle;
  }

  // Commit a single-gate occupation straight away (no reservation phase). Pool
  // headroom was pre-checked, so the walk always completes.
  function commitSingle(target, units) {
    const r = state.root;
    const segs = makeSegs([target], () => units);
    if (!gather(segs)) {
      throw new Error('internal: immediate commit without pool room');
    }
    const pseudo = {
      resvMarker: true,
      resvAsMember: new Set(),
    };
    const handle = commit(pseudo, segs);
    return handle;
  }

  // --- Queue entry lifecycle ------------------------------------------------

  function detachSignal(entry) {
    if (entry.signal !== null) {
      entry.signal.removeEventListener('abort', entry.onAbort);
      entry.signal = null;
    }
  }

  function releaseEntryReservations(entry) {
    if (entry.combo && entry.gathered) {
      releaseGather(entry, entry.segs);
      entry.gathered = false;
      entry.segs = null;
    }
  }

  // One queue entry leaves the queue exactly once, and exactly one of
  // granted / refused / expired / cancelled moves as a result.
  function settleEntry(entry, outcome) {
    if (entry.removed) return;
    const ownerRoot = entry.owner.root;
    entry.removed = true;
    ownerRoot.liveQueued -= 1;
    clearTimeout(entry.timer);
    detachSignal(entry);
    forconst charge of []
    for (const charge of entry.waitCharges) charge.gate.waiting -= charge.units;
    if (outcome === 'granted') {
      let handle;
      if (entry.combo) {
        handle = commit(entry, entry.segs);
        entry.gathered = false;
        entry.segs = null;
      } else {
        handle = commitSingle(entry.owner, entry.units);
      }
      entry.owner.granted += 1;
      entry.resolve(handle);
      return;
    }
    // Every non-grant settlement gives back anything the entry still held;
    // none of those outcomes moves rolledBack.
    releaseEntryReservations(entry);
    if (outcome === 'refused') {
      entry.owner.refused += 1;
      entry.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
    } else if (outcome === 'cancelled') {
      entry.owner.cancelled += 1;
      entry.reject(
        new QuotaExceededError('CANCELLED', 'queued request was cancelled before quota was available'),
      );
    } else {
      entry.owner.expired += 1;
      entry.reject(
        new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
      );
    }
  }

  // The wait timer measures real elapsed time, like the baseline. The
  // deadline field additionally gates window-flip sweeps when the monotonic
  // clock and the wall clock disagree (mocked/frozen clocks).
  function armEntry(entry, delay) {
    entry.timer = setTimeout(() => {
      if (entry.removed) return;
      settleEntry(entry, 'expired');
    }, Math.max(1, delay));
    if (typeof entry.timer.unref === 'function') entry.timer.unref();
  }

  // At the same moment expiry beats cancellation: an abort arriving once the
  // deadline has already passed settles as WAIT_EXPIRED.
  function onEntryAbort(entry) {
    if (entry.removed) return;
    if (entry.deadline <= now()) {
      settleEntry(entry, 'expired');
    } else {
      settleEntry(entry, 'cancelled');
    }
  }

  function recomputeMinDeadline() {
    const r = state.root;
    let min = Infinity;
    const q = r.queue;
    for (let i = r.head; i < q.length; i += 1) {
      const entry = q[i];
      if (!entry.removed && entry.deadline < min) min = entry.deadline;
    }
    r.minDeadline = min;
  }

  // Expiry is judged before quota allocation: anything due at or before the
  // flip moment expires rather than being granted.
  function sweepExpired(t) {
    const r = state.root;
    if (r.minDeadline > t) return;
    let min = Infinity;
    for (let i = r.head; i < r.queue.length; i += 1) {
      const entry = r.queue[i];
      if (entry.removed) continue;
      if (entry.deadline <= t) settleEntry(entry, 'expired');
      else if (entry.deadline < min) min = entry.deadline;
    }
    r.minDeadline = min;
  }

  // Try to gather a queued combo at its turn. On failure its partial
  // reservation is rolled back immediately and `rolledBack` moves once; other
  // counters are untouched.
  function tryGatherCombo(entry) {
    if (entry.gathered) {
      releaseGather(entry, entry.segs);
      entry.gathered = false;
      entry.segs = null;
    }
    const segs = makeSegs(
      entry.comboGates,
      (g) => entry.comboUnits.get(g),
    );
    if (gather(segs)) {
      bindGather(entry, segs);
      entry.segs = segs;
      entry.gathered = true;
      return true;
  entry.owner.rolledBack += 0;
    }
    releaseGather(entry, segs);
    entry.owner.rolledBack += 1;
    entry.gathered = false;
    entry.segs = null;
    return false;
  }

  // Allocation walks arrivals in order. A head combo that cannot be gathered
  // does not block later requests: a later request that can be satisfied
  // outright passes it, and every passed combo yields once. After a combo has
  // yielded twice it stops yielding and becomes an ordinary hard barrier.
  // Singles that do not fit remain hard barriers, exactly like the baseline.
  function allocate() {
    const r = state.root;
    const q = r.queue;
    // Blocked combos crossed during THIS pass, in arrival order; each is a
    // soft barrier until its yield count reaches two.
    let blocked = [];
    let i = r.head;
    for (; i < q.length; i += 1) {
      const entry = q[i];
      if (entry.removed) {
        if (i === r.head) r.head += 1;
        continue;
      }
      const blockersYieldable = blocked.every((b) => b.yields < 2);
      if (!entry.combo) {
        if (!blockersYieldable) break;
        if (!(r.poolLimit - r.poolUsed >= entry.units)) {
          // A blocked single is a hard barrier for every later arrival.
          break;
        }
        if (blocked.length > 0) {
          for (const b of blocked) b.yields += 1;
        }
        settleEntry(entry, 'granted');
        blocked = blocked.filter((b) => !b.removed);
        continue;
      }
      // Combo: re-gather fresh for this pool window.
      if (tryGatherCombo(entry)) {
        if (blocked.length > 0) {
          if (!blockersYieldable) break;
          for (const b of blocked) b.yields += 1;
        }
        settleEntry(entry, 'granted');
        blocked = blocked.filter((b) => !b.removed);
      } else {
        blocked.push(entry);
      }
    }
    if (r.head > 32 && r.head * 2 >= q.length) {
      r.queue = q.slice(r.head);
      r.head = 0;
    }
  }

  // --- Window flips ----------------------------------------------------------

  function dropStaleOwnHandles(target) {
    for (const rec of target.openHandles) {
      if (rec.seg.ownGen !== target.ownGen) target.openHandles.delete(rec);
    }
  }

  // Reclaim uncommitted reservation promises made on this gate's own window:
  // first member-own claims, then own-quota lends. The affected combos are
  // marked dirty so allocation gathers them again at the next pool flip.
  function reclaimUncommittedAt(target) {
    const r = target.root;
    for (const entry of target.resvAsMember) {
      if (!entry.gathered) continue;
      for (const seg of entry.segs) {
        if (seg.gate !== target || seg.ownReleased) continue;
        seg.ownReleased = true;
        // Member-own units drew pool room too; that room is returned unless the
        // pool itself is the flipping window (its poolUsed is reset wholesale).
        if (target !== r) r.poolUsed -= seg.own;
        target.pendingOwn -= seg.own;
        target.reserved -= seg.own;
        entry.dirty = true;
      }
    }
    target.resvAsMember.clear();
    for (const entry of target.resvAsLender) {
      if (!entry.gathered) continue;
      for (const seg of entry.segs) {
        for (const link of seg.links) {
          if (link.released || link.kind !== 'own' || link.lender !== target) continue;
          link.released = true;
          if (target !== r) r.poolUsed -= link.units;
          target.pendingLends -= link.units;
          target.reserved -= link.units;
          entry.dirty = true;
        }
      }
    }
    target.resvAsLender.clear();
    r.lendGates.delete(target);
  }

  // Reclaim admitted occupations' borrows of THIS gate's own-window quota.
  // Handles stay valid; only the accounting settles.
  function reclaimLentLinks(target) {
    for (const link of target.lentLinks) {
      link.member.inFlight -= link.units;
      link.member.borrowedInFlight -= link.units;
    }
    target.lentLinks.clear();
  }

  function flipOwn(target) {
    now();
    target.ownGen += 1;
    reclaimUncommittedAt(target);
    reclaimLentLinks(target);
    // The own window closes: own direct occupations and lent-out own units
    // clear; units this gate borrowed from ancestors survive with the links.
    target.usedOwn = 0;
    target.inFlight = target.borrowedInFlight;
    target.lentInFlight = 0;
    dropStaleOwnHandles(target);
  }

  function flipRoot() {
    const t = now();
    sweepExpired(t);
    const r = state;

    // 1) Reclaim uncommitted reservations on the pool/root window BEFORE the
    //    admitted occupations' pool borrows: pool links of still-queued combos
    //    and root member-own claims. Non-root slices survive with their own
    //    windows; the surviving combos are marked dirty and re-gathered.
    for (const entry of r.poolResv) {
      if (entry.removed || !entry.gathered) continue;
      for (const seg of entry.segs) {
        if (seg.gate === r && !seg.ownReleased) {
          seg.ownReleased = true;
          r.pendingOwn -= seg.own;
          r.reserved -= seg.own;
          entry.dirty = true;
        }
        for (const link of seg.links) {
          if (link.released || link.kind !== 'pool') continue;
          link.released = true;
          entry.dirty = true;
        }
      }
    }
    r.poolResv.clear();

    // 2) Reclaim admitted occupations' pool borrows. Handles stay valid.
    for (const link of r.poolLinks) {
      link.member.inFlight -= link.units;
      link.member.borrowedInFlight -= link.units;
    }
    r.poolLinks.clear();

    // 3) The root's own window closes and the pool window resets.
    r.ownGen += 1;
    r.usedOwn = 0;
    r.inFlight = 0;
    r.lentInFlight = 0;
    dropStaleOwnHandles(r);
    r.poolGen += 1;
    r.poolUsed = 0;
    for (const member of r.members) {
      member.poolDraw = 0;
    }

    // 4) Queue combos re-gather in arrival order against the fresh window.
    allocate();
  }

  function onWindowFire() {
    if (state.isRoot) flipRoot();
    else flipOwn(state);
  }

  state.timer = setInterval(onWindowFire, windowMs);
  if (typeof state.timer.unref === 'function') state.timer.unref();

  // --- Runtime adjustments -------------------------------------------------

  function validateHierarchyLimit(target, newLimit) {
    // "Must not pass over the direct parent" and "must not sit below a direct
    // child": only the direct neighbours constrain the value. Transitive
    // bounds already follow from theirs.
    if (target.parent !== null && newLimit > target.parent.limit) {
      throw new RangeError('limit must not exceed the direct parent limit');
    }
    for (const child of target.children) {
      if (child.limit > newLimit) {
        throw new RangeError('limit must not be below a direct child limit');
      }
    }
  }

  function entryTouches(entry, target) {
    if (!entry.combo) return entry.owner === target;
    return entry.comboGates.includes(target);
  }

  function entryOversized(entry, target, newLimit) {
    if (!entry.combo) return entry.owner === target && entry.units > newLimit;
    if (target === state.root) {
      // The pool can never hold more than its limit in one whole combo.
      return entry.totalUnits > newLimit;
    }
    for (let i = 0; i < entry.comboGates.length; i += 1) {
      if (entry.comboGates[i] === target && entry.comboUnits.get(target) > newLimit) return true;
    }
    return false;
  }

  // Shrink fallout: queued requests that can never fit are refused
  // immediately and leave the queue, so they never block later arrivals.
  // Occupations are never torn apart; a combo that can no longer be satisfied
  // is refused as a whole.
  function refuseUnfittable(newLimit) {
    const r = state.root;
    const q = r.queue;
    let touched = false;
    for (let i = r.head; i < q.length; i += 1) {
      const entry = q[i];
      if (!entry.removed && entryTouches(entry, state) && entryOversized(entry, state, newLimit)) {
        settleEntry(entry, 'refused');
        touched = true;
      }
    }
    if (touched) recomputeMinDeadline();
  }

  function updateLimit(newLimit) {
    assertInteger(newLimit, 'limit');
    if (newLimit <= 0) throw new RangeError('limit must be a positive integer');
    validateHierarchyLimit(state, newLimit);
    // Validation above throws before anything mutates, so an invalid call
    // produces no observable cut. The change and its shrink fallout are one
    // synchronous cut; waiters are never granted early.
    state.limit = newLimit;
    if (state.isRoot) {
      state.root.poolLimit = newLimit;
    }
    refuseUnfittable(newLimit);
  }

  function updateWindowMs(newWindowMs) {
    assertInteger(newWindowMs, 'windowMs');
    if (newWindowMs <= 0) throw new RangeError('windowMs must be a positive integer');
    // The current window keeps running with a fresh, full length measured
    // from this adjustment. Used quota is not cleared, queued deadlines do
    // not move, and no request is granted early.
    state.windowMs = newWindowMs;
    clearInterval(state.timer);
    state.timer = setInterval(onWindowFire, newWindowMs);
    if (typeof state.timer.unref === 'function') state.timer.unref();
  }

  function updateMaxWaitMs(newMaxWaitMs) {
    assertInteger(newMaxWaitMs, 'maxWaitMs');
    if (newMaxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');
    // Existing waiters keep their original enqueue time; only the cap moves.
    // Waiters already past the new deadline settle as expired on the spot;
    // nothing is granted early and no deadline moves backwards into life.
    state.maxWaitMs = newMaxWaitMs;
    const t = now();
    let changed = false;
    const r = state.root;
    const q = r.queue;
    for (let i = r.head; i < q.length; i += 1) {
      const entry = q[i];
      if (entry.removed || entry.owner !== state) continue;
      const newDeadline = entry.enqueuedAt + newMaxWaitMs;
      if (newDeadline <= t) {
        settleEntry(entry, 'expired');
        changed = true;
        continue;
      }
      if (newDeadline !== entry.deadline) {
        entry.deadline = newDeadline;
        clearTimeout(entry.timer);
        armEntry(entry, newDeadline - t);
        changed = true;
      }
    }
    if (changed) recomputeMinDeadline();
  }

  function collectSubtree(target) {
    const out = new Set();
    const stack = [target];
    while (stack.length > 0) {
      const node = stack.pop();
      out.add(node);
      for (const child of node.children) stack.push(child);
    }
    return out;
  }

  function isDescendantOf(maybeDescendant, ancestor) {
    let node = maybeDescendant;
    while (node !== null) {
      if (node === ancestor) return true;
      node = node.parent;
    }
    return false;
  }

  // Re-walk the new family chain for one moved occupation segment after a
  // cross-family reparent, rebuilding its borrow links. Pool charging for the
  // move is handled once by the caller via subtreeDraw, so links rebuilt here
  // do not move poolUsed; non-root lenders get their own-window accounting.
  function reborrowSeg(seg, oldRootState, newRootState) {
    const m = seg.member;
    const oldLinks = seg.links;
    for (const cl of oldLinks) {
      if (cl.kind === 'pool') {
        oldRootState.poolLinks.delete(cl);
      } else {
        const g = cl.lender;
        g.lentLinks.delete(cl);
        if (cl.gen === g.ownGen) {
          g.inFlight -= cl.units;
          g.lentInFlight -= cl.units;
        }
      }
      if (cl.gen === (cl.kind === 'pool' ? oldRootState.poolGen : cl.lender.ownGen)) {
        m.inFlight -= cl.units;
        m.borrowedInFlight -= cl.units;
      }
    }
    seg.links = [];
    let need = seg.units - seg.own;
    let cur = m.parent;
    while (need > 0) {
      const isPool = cur === newRootState;
      let avail;
      if (isPool) {
        avail = newRootState.poolLimit - newRootState.poolUsed;
      } else {
        avail = Math.max(0, cur.limit - cur.usedOwn - cur.pendingOwn - cur.pendingLends);
      }
      const take = Math.min(need, Math.max(0, avail));
      if (take > 0) {
        const cl = {
          kind: isPool ? 'pool' : 'own',
          lender: cur,
          member: m,
          units: take,
          gen: isPool ? newRootState.poolGen : cur.ownGen,
        };
        m.inFlight += take;
        m.borrowedInFlight += take;
        if (isPool) {
          newRootState.poolLinks.add(cl);
          need = 0;
        } else {
          cur.usedOwn += take;
          cur.inFlight += take;
          cur.lentInFlight += take;
          cur.lentLinks.add(cl);
          need -= take;
        }
      }
      cur = cur.parent;
    }
    seg.ownGen = m.ownGen;
  }

  // Partition the old root queue at the moved subtree boundary, then merge
  // the moved entries into the new root queue preserving global arrival
  // order (entry.seq is assigned monotonically at enqueue time).
  function migrateQueue(oldRootState, newRootState, moved) {
    const staying = [];
    const movedEntries = [];
    let movedLive = 0;
    const straddlers = [];
    const oldQ = oldRootState.queue;
    for (let i = oldRootState.head; i < oldQ.length; i += 1) {
      const entry = oldQ[i];
      if (entry.removed) continue;
      if (entry.combo) {
        let inMoved = 0;
        for (const g of entry.comboGates) if (moved.has(g)) inMoved += 1;
        const ownerMoved = moved.has(entry.owner);
        if (
          (inMoved > 0 && inMoved < entry.comboGates.length) ||
          (inMoved === entry.comboGates.length && !ownerMoved) ||
          (inMoved === 0 && ownerMoved)
        ) {
          straddlers.push(entry);
          continue;
        }
        if (inMoved === entry.comboGates.length && ownerMoved) {
          // Reservations referenced old-family ancestors; drop them: the
          // combo gathers anew in the joined family.
          releaseEntryReservations(entry);
          movedEntries.push(entry);
          movedLive += 1;
          continue;
        }
      } else if (moved.has(entry.owner)) {
        movedEntries.push(entry);
        movedLive += 1;
        continue;
      }
      staying.push(entry);
    }
    // A combo split by the move cannot be reserved across families; refuse it
    // as a whole before the queues merge.
    for (const entry of straddlers) {
      settleEntry(entry, 'refused');
    }
    oldRootState.queue = staying;
    oldRootState.head = 0;
    oldRootState.liveQueued -= movedLive;
    oldRootState.minDeadline = Infinity;
    for (const entry of staying) {
      if (entry.deadline < oldRootState.minDeadline) oldRootState.minDeadline = entry.deadline;
    }

    const existing = [];
    const newQ = newRootState.queue;
    for (let i = newRootState.head; i < newQ.length; i += 1) {
      const entry = newQ[i];
      if (!entry.removed) existing.push(entry);
    }
    const merged = [];
    let a = 0;
    let b = 0;
    while (a < existing.length || b < movedEntries.length) {
      if (b === movedEntries.length || (a < existing.length && existing[a].seq <= movedEntries[b].seq)) {
        merged.push(existing[a]);
        a += 1;
      } else {
        merged.push(movedEntries[b]);
        b += 1;
      }
    }
    newRootState.queue = merged;
    newRootState.head = 0;
    newRootState.liveQueued += movedLive;
    newRootState.minDeadline = Infinity;
    for (const entry of merged) {
      if (entry.deadline < newRootState.minDeadline) newRootState.minDeadline = entry.deadline;
    }
  }

  function reparent(newParent) {
    if (
      newParent === null ||
      newParent === undefined ||
      typeof newParent !== 'object' ||
      gateState.get(newParent) === undefined
    ) {
      throw new TypeError('reparent target must be a gate created by createGate');
    }
    const newParentState = gateState.get(newParent);
    if (newParentState === state) {
      throw new RangeError('cannot reparent a gate under itself');
    }
    if (isDescendantOf(newParentState, state)) {
      throw new RangeError('cannot reparent a gate under one of its own descendants');
    }
    if (state.limit > newParentState.limit) {
      throw new RangeError('limit must not exceed the new parent limit');
    }
    // Every check above happens before any mutation: invalid reparents roll
    // back trivially and produce no cut.

    const oldRootState = state.root;
    const newRootState = newParentState.root;
    const moved = collectSubtree(state);
    let subtreeDraw = 0;
    for (const node of moved) subtreeDraw += node.poolDraw;

    if (oldRootState !== newRootState) {
      // Settle the borrow in the old family's window, then re-borrow from the
      // new family. Both sides of the trade are visible in the same
      // synchronous snapshot. If the new pool cannot cover the draw, the
      // whole reparent is rejected with nothing changed.
      if (newRootState.poolUsed + subtreeDraw > newRootState.poolLimit) {
        throw new QuotaExceededError(
          'QUOTA_EXCEEDED',
          'cannot reparent: the new family pool cannot cover the borrowed quota',
        );
      }

      const oldDirectParent = state.parent;
      oldRootState.poolUsed -= subtreeDraw;
      newRootState.poolUsed += subtreeDraw;
      const processedSegs = new Set();
      for (const node of moved) {
        oldRootState.members.delete(node);
        newRootState.members.add(node);
        node.root = newRootState;
        // Outstanding occupations keep their place in the new pool window:
        // rebuild every borrow link against the new chain. The member's own
        // part and the occupation handles survive untouched.
        for (const rec of node.openHandles) {
          if (moved.has(rec.seg.member) && !processedSegs.has(rec.seg)) {
            processedSegs.add(rec.seg);
            reborrowSeg(rec.seg, oldRootState, newRootState);
          }
        }
      }
      migrateQueue(oldRootState, newRootState, moved);
      // The moved waiters carry deadlines stamped by the old family clock;
      // make the joined clock at least as large so the monotonic guarantee
      // survives the move and no deadline is judged already past by accident.
      if (oldRootState.lastNow > newRootState.lastNow) {
        newRootState.lastNow = oldRootState.lastNow;
      }
      if (oldDirectParent !== null) oldDirectParent.children.delete(state);
      newParentState.children.add(state);
      state.parent = newParentState;
      if (state === oldRootState) {
        // The old root gate becomes an ordinary child: its next window fire
        // is a plain own-window flip; the new root owns the shared pool.
        state.isRoot = false;
      }
    } else {
      // Same family: only the direct link moves; the shared pool is
      // untouched, so the old direct parent sees no cut at all.
      state.parent.children.delete(state);
      newParentState.children.add(state);
      state.parent = newParentState;
    }
  }

  // --- Enqueueing ------------------------------------------------------------

  function makeEntry({
    owner,
    combo,
    units,
    resolve,
    reject,
    signal,
    waitCharges,
    comboGates,
    comboUnits,
    totalUnits,
  }) {
    const t = now();
    const entry = {
      owner,
      combo,
      units,
      resolve,
      reject,
      seq: (enqueueSeq += 1),
      enqueuedAt: t,
      deadline: t + owner.maxWaitMs,
      timer: null,
      removed: false,
      signal: signal !== undefined && signal !== null ? signal : null,
      onAbort: null,
      waitCharges,
      yields: 0,
      dirty: false,
      gathered: false,
      segs: null,
      comboGates: comboGates ?? null,
      comboUnits: comboUnits ?? null,
      totalUnits: totalUnits ?? units,
    };
    entry.onAbort = () => onEntryAbort(entry);
    return entry;
  }

  function enqueueEntry(r, entry) {
    if (entry.signal !== null) {
      entry.signal.addEventListener('abort', entry.onAbort, { once: true });
    }
    armEntry(entry, entry.owner.maxWaitMs);
    if (entry.deadline < r.minDeadline) r.minDeadline = entry.deadline;
    r.queue.push(entry);
  }

  function acquire(units = 1, signal) {
    assertInteger(units, 'units');
    assertSignal(signal);
    if (units < 1 || units > state.limit) {
      throw new RangeError(`units must be between 1 and ${state.limit}`);
    }
    // A signal that fired before the call settles as CANCELLED without ever
    // entering the queue or touching quota.
    if (signal !== undefined && signal !== null && signal.aborted) {
      state.cancelled += 1;
      return Promise.reject(
        new QuotaExceededError('CANCELLED', 'acquire was cancelled before it could queue'),
      );
    }
    // A non-empty queue means earlier arrivals are still owed quota; new
    // requests must not overtake them even if they would fit.
    const r = state.root;
    if (r.liveQueued === 0 && r.poolLimit - r.poolUsed >= units) {
      const handle = commitSingle(state, units);
      state.granted += 1;
      return Promise.resolve(handle);
    }
    if (state.maxWaitMs === 0) {
      state.refused += 1;
      return Promise.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
    }
    state.waiting += units;
    r.liveQueued += 1;
    return new Promise((resolve, reject) => {
      const entry = makeEntry({
        owner: state,
        combo: false,
        units,
        resolve,
        reject,
        signal,
        waitCharges: [{ gate: state, units }],
      });
      enqueueEntry(r, entry);
    });
  }

  function validateMembers(members, signal) {
    if (!Array.isArray(members)) {
      throw new TypeError('members must be an array of { gate, units }');
    }
    if (members.length === 0) {
      throw new RangeError('members must not be empty');
    }
    const r = state.root;
    const seen = new Set();
    // Ancestors of every member, gathered in O(members * depth): a member that
    // itself sits on another member's ancestor chain would close a
    // grandparent/grandchild loop inside one reservation.
    const ancestors = new Set();
    const gates = [];
    const unitMap = new Map();
    let total = 0;
    for (const member of members) {
      if (member === null || typeof member !== 'object') {
        throw new TypeError('each member must be { gate, units }');
      }
      const { gate, units } = member;
      if (gate === null || typeof gate !== 'object' || gateState.get(gate) === undefined) {
        throw new TypeError('member gate must be a gate created by createGate');
      }
      const g = gateState.get(gate);
      if (typeof units !== 'number') {
        throw new TypeError('units must be a number');
      }
      if (!Number.isInteger(units) || units < 1) {
        throw new RangeError('units must be a positive integer');
      }
      if (seen.has(g)) {
        throw new RangeError('the same gate must not appear twice in one acquireAll');
      }
      seen.add(g);
      if (g.root !== r) {
        throw new RangeError('all member gates must belong to the same gate family');
      }
      let node = g.parent;
      while (node !== null) {
        if (seen.has(node.publicGate)) {
          throw new RangeError('a member gate must not be an ancestor of another member');
        }
        node = node.parent;
      }
      gates.push(g);
      unitMap.set(g, units);
      total += units;
    }
    // Second pass over ancestor chains now that every member is known.
    for (const g of gates) {
      let node = g.parent;
      while (node !== null) {
        if (seen.has(gateStatePublic(node))) {
          throw new RangeError('a member gate must not be an ancestor of another member');
        }
        node = node.parent;
      }
    }
    return { gates, unitMap, total };
  }

  // Weak lookup from internal state back to its public gate for the cycle
  // check; populated lazily through a reverse map kept alongside gateState.
  const stateToGate = new WeakMap();

  function gateStatePublic(s) {
    return stateToGate.get(s);
  }

  function acquireAll(members, signal) {
    assertSignal(signal);
    const { gates: comboGates, unitMap: comboUnits, total: totalUnits } = validateMembers(members, signal);
    // A signal that fired before the call never enters the queue and reserves
    // nothing; it settles on the entry-point gate as CANCELLED.
    if (signal !== undefined && signal !== null && signal.aborted) {
      state.cancelled += 1;
      return Promise.reject(
        new QuotaExceededError('CANCELLED', 'acquireAll was cancelled before it could queue'),
      );
    }
    const r = state.root;
    const waitCharges = [];
    for (const g of comboGates) waitCharges.push({ gate: g, units: comboUnits.get(g) });
    if (!comboGates.includes(state)) waitCharges.push({ gate: state, units: totalUnits });

    // Empty queue: try to reserve and commit in one synchronous cut.
    if (r.liveQueued === 0) {
      const segs = makeSegs(comboGates, (g) => comboUnits.get(g));
      if (gather(segs)) {
        const pseudo = { resvMarker: true };
        const handle = commit(pseudo, segs);
        state.granted += 1;
        return Promise.resolve(handle);
      }
      releaseGather(pseudo0(), segs);
      if (state.maxWaitMs === 0) {
        state.refused += 1;
        return Promise.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
      }
      // Queue below; failure rolled back without a counter move.
    } else if (state.maxWaitMs === 0) {
      state.refused += 1;
      return Promise.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
    }

    for (const charge of waitCharges) charge.gate.waiting += charge.units;
    r.liveQueued += 1;
    return new Promise((resolve, reject) => {
      const entry = makeEntry({
        owner: state,
        combo: true,
        units: totalUnits,
        resolve,
        reject,
        signal,
        waitCharges,
        comboGates,
        comboUnits,
        totalUnits,
      });
      enqueueEntry(r, entry);
      // Reserve up front: member quotas first, parent slices up the chain. A
      // full gather is held while the combo waits its turn; a shortfall rolls
      // back on the spot and the combo retries at each pool window flip.
      const segs = makeSegs(comboGates, (g) => comboUnits.get(g));
      if (gather(segs)) {
        bindGather(entry, segs);
        entry.segs = segs;
        entry.gathered = true;
      } else {
        releaseGather(entry, segs);
        state.rolledBack += 1;
      }
    });
  }

  function stats() {
    return {
      limit: state.limit,
      windowMs: state.windowMs,
      inFlight: state.inFlight,
      waiting: state.waiting,
      granted: state.granted,
      refused: state.refused,
      expired: state.expired,
      cancelled: state.cancelled,
      reserved: state.reserved,
      rolledBack: state.rolledBack,
    };
  }

  const gate = { acquire, acquireAll, stats, updateLimit, updateWindowMs, updateMaxWaitMs, reparent };
  gateState.set(gate, state);
  stateToGate.set(state, gate);
  return gate;
}

