export class QuotaExceededError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'QuotaExceededError';
    this.code = code;
  }
}

// Internal state of every gate, shared with child gates through a WeakMap so
// the public gate object keeps its exact shape.
const gateState = new WeakMap();

// Monotonic counter that never repeats or moves backwards, independent of the
// (mocked, possibly frozen) wall clock; gives queued entries a global arrival
// order so reparented queues can merge fairly.
let enqueueSeq = 0;

function assertInteger(value, name) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new TypeError(`${name} must be an integer`);
  }
}

function assertSignal(signal) {
  if (
    signal !== undefined &&
    signal !== null &&
    (typeof signal !== 'object' ||
      typeof signal.addEventListener !== 'function' ||
      typeof signal.removeEventListener !== 'function')
  ) {
    throw new TypeError('signal must be an AbortSignal');
  }
}

export function createGate({ limit, windowMs, maxWaitMs = 0, parent } = {}) {
  assertInteger(limit, 'limit');
  assertInteger(windowMs, 'windowMs');
  assertInteger(maxWaitMs, 'maxWaitMs');
  if (limit <= 0) throw new RangeError('limit must be a positive integer');
  if (windowMs <= 0) throw new RangeError('windowMs must be a positive integer');
  if (maxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');

  let parentState = null;
  if (parent !== undefined && parent !== null) {
    parentState = gateState.get(parent);
    if (parentState === undefined) {
      throw new TypeError('parent must be a gate created by createGate');
    }
    if (limit > parentState.limit) {
      throw new RangeError('limit must not exceed parent limit');
    }
  }

  const state = {
    limit,
    windowMs,
    maxWaitMs,
    parent: parentState,
    children: new Set(),
    isRoot: parentState === null,
    // Own-window accounting.
    ownGen: 0, // bumped on every own-window flip, invalidates old handles
    usedOwn: 0, // own units occupied or lent out in the current own window
    inFlight: 0, // units occupied through this gate and not yet cleared
    borrowedInFlight: 0, // units this gate's own occupations borrowed, still live
    lentInFlight: 0, // own units lent to descendants' admitted occupations
    poolDraw: 0, // units charged into the root pool window tagged drawGen
    drawGen: -1,
    // Cross-gate reservation accounting. A queued acquireAll reserves member
    // own-window slices first, then own slices up the direct-parent chain; the
    // root pool itself is only charged when the whole combo commits.
    reserved: 0, // stat: pendingOwn + pendingLends on this gate
    rolledBack: 0, // stat: failed commit attempts owned by this gate
    pendingOwn: 0, // own units promised to queued combos where this is a member
    pendingLends: 0, // own units promised to queued combos as an ancestor lender
    resvAsMember: new Set(), // entries holding pendingOwn here
    resvAsLender: new Set(), // entries holding pendingLends here
    lentLinks: new Set(), // admitted occupation links lent from this gate
    // Observability.
    waiting: 0, // units currently queued through this gate
    granted: 0,
    refused: 0,
    expired: 0,
    cancelled: 0,
    openHandles: new Set(),
    root: null,
    timer: null,
  };

  let root;
  if (parentState === null) {
    root = state;
    // The quota pool shared by the whole hierarchy lives on the root gate.
    Object.assign(state, {
      poolLimit: limit,
      poolGen: 0, // bumped on every root-window flip
      poolUsed: 0, // units committed through every gate in the current pool window
      poolLinks: new Set(), // admitted pool borrows, reclaimed at the pool flip
      queue: [], // queued requests from every gate, in arrival order
      head: 0, // index of the first live entry; entries are never shifted
      liveQueued: 0, // entries not yet settled
      minDeadline: Infinity, // earliest live deadline, skips idle sweeps
      lastNow: 0, // monotonic clock: never moves backwards
      members: new Set(),
    });
    state.members.add(state);
  } else {
    root = parentState.root;
    root.members.add(state);
    parentState.children.add(state);
  }
  state.root = root;

  // Operational helpers read state.root dynamically rather than capturing the
  // local `root`: reparent() can move this gate (and its descendants) into
  // another family's pool.
  function now() {
    const r = state.root;
    const t = Date.now();
    if (t > r.lastNow) r.lastNow = t;
    return r.lastNow;
  }

  function effectiveDraw(node) {
    return node.drawGen === node.root.poolGen ? node.poolDraw : 0;
  }

  function chargeDraw(node, units) {
    if (node.drawGen !== node.root.poolGen) {
      node.drawGen = node.root.poolGen;
      node.poolDraw = 0;
    }
    node.poolDraw += units;
  }

  // --- Combo reservation segments ------------------------------------------
  //
  // Gather: each member covers units with its own current-window quota; the
  // shortfall borrows own slices from the direct parent, then the grandparent,
  // and so on up to (but not including) the root. Anything still uncovered is
  // the pool shortfall, promised only when the combo commits. Every mutation
  // touches only the member/ancestor chains involved: O(members * depth) per
  // attempt, with intrusive sets keeping commit, rollback and window reclaims
  // off the global queue and the family member set.

  function buildSegs(comboGates, unitsOf) {
    return comboGates.map((g) => ({
      gate: g,
      units: unitsOf(g),
      own: 0,
      ownReleased: false,
      links: [], // { lender, units, released }
      poolShort: 0,
    }));
  }

  function ownHeadroom(g) {
    return Math.max(0, g.limit - g.usedOwn - g.pendingOwn - g.pendingLends);
  }

  // Place the own-slice reservation. Always completes structurally: chains end
  // at the root pool, whose shortfall is deferred to commit time.
  function gatherHolds(entry, segs) {
    const r = entry.owner.root;
    for (const seg of segs) {
      const m = seg.gate;
      if (m === r) {
        seg.poolShort = seg.units;
        continue;
      }
      let need = seg.units;
      let take = Math.min(need, ownHeadroom(m));
      seg.own = take;
      m.pendingOwn += take;
      m.reserved += take;
      m.resvAsMember.add(entry);
      need -= take;
      let cur = m.parent;
      while (need > 0 && cur !== null && cur !== r) {
        take = Math.min(need, ownHeadroom(cur));
        if (take > 0) {
          cur.pendingLends += take;
          cur.reserved += take;
          cur.resvAsLender.add(entry);
          seg.links.push({ lender: cur, units: take, released: false });
          need -= take;
        }
        cur = cur.parent;
      }
      seg.poolShort = need;
    }
    entry.segs = segs;
    entry.holdsHeld = true;
  }

  // Release every live own-slice hold. Links a lender window flip already
  // reclaimed are marked released and skipped, so this stays correct after a
  // partial reclaim. Never touches poolUsed: holds never charged the pool.
  function releaseHolds(entry) {
    if (!entry.holdsHeld || entry.segs === null) return;
    for (const seg of entry.segs) {
      const m = seg.gate;
      const r = m.root;
      if (!seg.ownReleased && seg.own > 0) {
        seg.ownReleased = true;
        m.pendingOwn -= seg.own;
        m.reserved -= seg.own;
      }
      m.resvAsMember.delete(entry);
      for (const link of seg.links) {
        if (link.released) continue;
        link.released = true;
        const g = link.lender;
        g.pendingLends -= link.units;
        g.reserved -= link.units;
        g.resvAsLender.delete(entry);
      }
    }
    entry.holdsHeld = false;
  }

  function regather(entry) {
    releaseHolds(entry);
    gatherHolds(entry, buildSegs(entry.comboGates, (g) => entry.comboUnits.get(g)));
  }

  // --- Handles --------------------------------------------------------------
  //
  // Every handle exposes exactly one own property, the release method, as a
  // closure: destructuring it and calling it without a receiver works. One
  // record per member gate; links remember the generations of both sides so a
  // release after either window flipped never subtracts reclaimed quota.

  function makeHandle(records) {
    let active = true;
    return {
      release() {
        if (!active) return;
        active = false;
        for (const rec of records) {
          const seg = rec.seg;
          const m = seg.member;
          const r = m.root;
          m.openHandles.delete(rec);
          if (seg.mgen === m.ownGen) {
            m.inFlight -= seg.own;
          }
          for (const link of seg.links) {
            const memberLive = seg.mgen === m.ownGen;
            const lenderLive =
              link.kind === 'pool'
                ? link.lgen === r.poolGen
                : link.lgen === link.lender.ownGen;
            if (!memberLive || !lenderLive) continue; // a window flip settled it
            m.inFlight -= link.units;
            m.borrowedInFlight -= link.units;
            if (link.kind === 'pool') {
              r.poolLinks.delete(link);
            } else {
              link.lender.lentLinks.delete(link);
              link.lender.inFlight -= link.units;
              link.lender.lentInFlight -= link.units;
            }
          }
        }
      },
    };
  }

  // Commit a single-gate occupation with the baseline partition: own quota
  // first, every shortfall drawn straight from the root pool.
  function commitSingle(target, units) {
    const r = target.root;
    r.poolUsed += units;
    chargeDraw(target, units);
    let seg;
    if (target === r) {
      target.usedOwn += units;
      target.inFlight += units;
      seg = { member: target, units, own: units, mgen: target.ownGen, links: [] };
    } else {
      const ownPart = Math.min(units, Math.max(0, target.limit - target.usedOwn));
      const borrowPart = units - ownPart;
      target.usedOwn += ownPart;
      target.inFlight += units;
      target.borrowedInFlight += borrowPart;
      const links = [];
      if (borrowPart > 0) {
        const link = {
          kind: 'pool',
          lender: r,
          member: target,
          units: borrowPart,
          lgen: r.poolGen,
          mgen: target.ownGen,
        };
        r.poolLinks.add(link);
        links.push(link);
      }
      seg = { member: target, units, own: ownPart, mgen: target.ownGen, links };
    }
    const rec = { seg };
    target.openHandles.add(rec);
    return makeHandle([rec]);
  }

  // Commit a fully gathered combo: reserved own slices become occupations,
  // ancestor lends become admitted links, and every unit draws the pool.
  function commitCombo(entry) {
    const r = entry.owner.root;
    const records = [];
    for (const seg0 of entry.segs) {
      const m = seg0.gate;
      const units = seg0.units;
      r.poolUsed += units;
      chargeDraw(m, units);
      let seg;
      if (m === r) {
        m.usedOwn += units;
        m.inFlight += units;
        seg = { member: m, units, own: units, mgen: m.ownGen, links: [] };
      } else {
        const ownPart = seg0.own;
        m.usedOwn += ownPart;
        m.pendingOwn -= ownPart;
        m.reserved -= ownPart;
        m.resvAsMember.delete(entry);
        m.inFlight += units;
        const links = [];
        for (const l0 of seg0.links) {
          const g = l0.lender;
          g.usedOwn += l0.units;
          g.pendingLends -= l0.units;
          g.reserved -= l0.units;
          g.resvAsLender.delete(entry);
          g.inFlight += l0.units;
          g.lentInFlight += l0.units;
          const link = {
            kind: 'own',
            lender: g,
            member: m,
            units: l0.units,
            lgen: g.ownGen,
            mgen: m.ownGen,
          };
          g.lentLinks.add(link);
          links.push(link);
        }
        const poolPart = seg0.poolShort;
        if (poolPart > 0) {
          const link = {
            kind: 'pool',
            lender: r,
            member: m,
            units: poolPart,
            lgen: r.poolGen,
            mgen: m.ownGen,
          };
          r.poolLinks.add(link);
          links.push(link);
        }
        m.borrowedInFlight += units - ownPart;
        seg = { member: m, units, own: ownPart, mgen: m.ownGen, links };
      }
      const rec = { seg };
      m.openHandles.add(rec);
      records.push(rec);
    }
    entry.holdsHeld = false;
    entry.segs = null;
    return makeHandle(records);
  }

  // --- Queue entry lifecycle ------------------------------------------------

  function detachSignal(entry) {
    if (entry.signal !== null) {
      entry.signal.removeEventListener('abort', entry.onAbort);
      entry.signal = null;
    }
  }

  // One queue entry leaves the queue exactly once, and exactly one of
  // granted / refused / expired / cancelled moves as a result.
  function settleEntry(entry, outcome) {
    if (entry.removed) return;
    const ownerRoot = entry.owner.root;
    entry.removed = true;
    ownerRoot.liveQueued -= 1;
    clearTimeout(entry.timer);
    detachSignal(entry);
    for (const charge of entry.waitCharges) charge.gate.waiting -= charge.units;
    if (outcome === 'granted') {
      const handle = entry.combo ? commitCombo(entry) : commitSingle(entry.owner, entry.units);
      entry.owner.granted += 1;
      entry.resolve(handle);
      return;
    }
    // Every non-grant settlement gives back any own-slice hold; none of those
    // outcomes itself counts as a reservation rollback.
    if (entry.combo) releaseHolds(entry);
    if (outcome === 'refused') {
      entry.owner.refused += 1;
      entry.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
    } else if (outcome === 'cancelled') {
      entry.owner.cancelled += 1;
      entry.reject(
        new QuotaExceededError('CANCELLED', 'queued request was cancelled before quota was available'),
      );
    } else {
      entry.owner.expired += 1;
      entry.reject(
        new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
      );
    }
  }

  // The wait timer measures real elapsed time, like the baseline. The
  // deadline field additionally gates window-flip sweeps when the monotonic
  // clock and the wall clock disagree (mocked/frozen clocks).
  function armEntry(entry, delay) {
    entry.timer = setTimeout(() => {
      if (entry.removed) return;
      settleEntry(entry, 'expired');
    }, Math.max(1, delay));
    if (typeof entry.timer.unref === 'function') entry.timer.unref();
  }

  // At the same moment expiry beats cancellation: an abort arriving once the
  // deadline has already passed settles as WAIT_EXPIRED.
  function onEntryAbort(entry) {
    if (entry.removed) return;
    if (entry.deadline <= now()) {
      settleEntry(entry, 'expired');
    } else {
      settleEntry(entry, 'cancelled');
    }
  }

  function recomputeMinDeadline() {
    const r = state.root;
    let min = Infinity;
    const q = r.queue;
    for (let i = r.head; i < q.length; i += 1) {
      const entry = q[i];
      if (!entry.removed && entry.deadline < min) min = entry.deadline;
    }
    r.minDeadline = min;
  }

  // Expiry is judged before quota allocation: anything due at or before the
  // flip moment expires rather than being granted.
  function sweepExpired(t) {
    const r = state.root;
    if (r.minDeadline > t) return;
    let min = Infinity;
    for (let i = r.head; i < r.queue.length; i += 1) {
      const entry = r.queue[i];
      if (entry.removed) continue;
      if (entry.deadline <= t) settleEntry(entry, 'expired');
      else if (entry.deadline < min) min = entry.deadline;
    }
    r.minDeadline = min;
  }

  // Allocation walks arrivals in order. A head combo whose whole reservation
  // cannot be covered by the pool left in this fresh window does not block
  // later requests: a later request that fits outright passes it and the combo
  // yields once. After yielding twice it becomes a hard barrier, exactly like
  // a single that does not fit.
  function allocate() {
    const r = state.root;
    const q = r.queue;
    const blocked = []; // soft-blocked combos crossed in this pass, arrival order
    let i = r.head;
    for (; i < q.length; i += 1) {
      const entry = q[i];
      if (entry.removed) continue;
      const hardBarrierAhead = blocked.some((b) => b.yields >= 2 && !b.removed);
      if (!entry.combo) {
        if (hardBarrierAhead || r.poolUsed + entry.units > r.poolLimit) break;
        if (blocked.length > 0) {
          for (const b of blocked) if (!b.removed) b.yields += 1;
        }
        settleEntry(entry, 'granted');
        continue;
      }
      // The combo's turn: re-gather its own slices for this pool window, then
      // check the only hard dimension, the root pool, for the whole combo.
      regather(entry);
      if (r.poolUsed + entry.totalUnits <= r.poolLimit && !hardBarrierAhead) {
        if (blocked.length > 0) {
          for (const b of blocked) if (!b.removed) b.yields += 1;
        }
        settleEntry(entry, 'granted');
      } else {
        // Any step short: give back every slice and roll back as a whole;
        // rolledBack moves once, no other counter moves for this attempt.
        releaseHolds(entry);
        entry.owner.rolledBack += 1;
        blocked.push(entry);
      }
    }
    if (r.head > 32 && r.head * 2 >= q.length) {
      r.queue = q.slice(r.head);
      r.head = 0;
    }
  }

  // --- Window flips ----------------------------------------------------------

  // A non-root window flip reclaims quota borrowed FROM this gate, uncommitted
  // reservations first (member promises, then ancestor lends), then admitted
  // occupations' borrows. Handles never break.
  function flipOwn(target) {
    const t = now();
    const r = target.root;

    // 1) Uncommitted reservations on this gate's own window.
    for (const entry of target.resvAsMember) {
      if (entry.removed || !entry.holdsHeld) continue;
      for (const seg of entry.segs) {
        if (seg.gate !== target || seg.ownReleased) continue;
        seg.ownReleased = true;
        target.pendingOwn -= seg.own;
        target.reserved -= seg.own;
        entry.dirty = true;
      }
    }
    target.resvAsMember.clear();
    for (const entry of target.resvAsLender) {
      if (entry.removed || !entry.holdsHeld) continue;
      for (const seg of entry.segs) {
        for (const link of seg.links) {
          if (link.released || link.lender !== target) continue;
          link.released = true;
          target.pendingLends -= link.units;
          target.reserved -= link.units;
          entry.dirty = true;
        }
      }
    }
    target.resvAsLender.clear()

    // 2) Occupations admitted THROUGH this gate end with its own window. Their
    //    surviving borrow links are detached while their lender windows live;
    //    the pool window itself does not close, so no pool room frees early.
    for (const rec of target.openHandles) {
      for (const link of rec.seg.links) {
        if (link.kind === 'pool') {
          r.poolLinks.delete(link);
        } else if (link.lgen === link.lender.ownGen) {
          link.lender.lentLinks.delete(link);
          link.lender.inFlight -= link.units;
          link.lender.lentInFlight -= link.units;
        }
      }
    }
    target.openHandles.clear();

    // 3) Admitted lends FROM this gate: reclaim from the borrowing members;
    //    their handles stay valid, only their inFlight settles.
    for (const link of target.lentLinks) {
      if (link.mgen === link.member.ownGen) {
        link.member.inFlight -= link.units;
        link.member.borrowedInFlight -= link.units;
      }
    }
    target.lentLinks.clear();

    target.ownGen += 1;
    target.usedOwn = 0;
    target.inFlight = 0;
    target.borrowedInFlight = 0;
    target.lentInFlight = 0;
    target.pendingOwn = 0;
    target.pendingLends = 0;
    target.reserved = 0;
  }

  function flipRoot() {
    const t = now();
    const r = state;

    // Expiry is judged before quota allocation.
    sweepExpired(t);

    // Uncommitted combos never promised pool units, so there is nothing
    // uncommitted to reclaim here. Reclaim admitted pool borrows first; the
    // admitted occupations survive with their handles intact.
    for (const link of r.poolLinks) {
      if (link.mgen === link.member.ownGen) {
        link.member.inFlight -= link.units;
        link.member.borrowedInFlight -= link.units;
      }
    }
    r.poolLinks.clear();

    // The root's own occupations end with its own window.
    r.openHandles.clear();
    r.ownGen += 1;
    r.usedOwn = 0;
    r.inFlight = 0;
    r.borrowedInFlight = 0;
    r.lentInFlight = 0;

    // The pool window resets. Member poolDraw values are tagged per
    // generation, so no family-wide sweep is needed.
    r.poolGen += 1;
    r.poolUsed = 0;

    allocate();
  }

  function onWindowFire() {
    if (state.isRoot) flipRoot();
    else flipOwn(state);
  }

  state.timer = setInterval(onWindowFire, windowMs);
  if (typeof state.timer.unref === 'function') state.timer.unref();

  // --- Runtime adjustments -------------------------------------------------

  function validateHierarchyLimit(target, newLimit) {
    // "Must not pass over the direct parent" and "must not sit below a direct
    // child": only the direct neighbours constrain the value. Transitive
    // bounds already follow from theirs.
    if (target.parent !== null && newLimit > target.parent.limit) {
      throw new RangeError('limit must not exceed the direct parent limit');
    }
    for (const child of target.children) {
      if (child.limit > newLimit) {
        throw new RangeError('limit must not be below a direct child limit');
      }
    }
  }

  function entryTouches(entry, target) {
    if (!entry.combo) return entry.owner === target;
    return entry.comboGates.includes(target);
  }

  function entryOversized(entry, target, newLimit) {
    if (!entry.combo) return entry.owner === target && entry.units > newLimit;
    if (target === state.root) return entry.totalUnits > newLimit;
    return entry.comboUnits.get(target) > newLimit;
  }

  // Shrink fallout: queued requests that can never fit are refused
  // immediately and leave the queue, so they never block later arrivals.
  // Occupations are never torn apart; a combo that can no longer be satisfied
  // is refused as a whole, releasing its reservation in the same cut.
  function refuseUnfittable(newLimit) {
    const r = state.root;
    const q = r.queue;
    let touched = false;
    for (let i = r.head; i < q.length; i += 1) {
      const entry = q[i];
      if (!entry.removed && entryTouches(entry, state) && entryOversized(entry, state, newLimit)) {
        settleEntry(entry, 'refused');
        touched = true;
      }
    }
    if (touched) recomputeMinDeadline();
  }

  function updateLimit(newLimit) {
    assertInteger(newLimit, 'limit');
    if (newLimit <= 0) throw new RangeError('limit must be a positive integer');
    validateHierarchyLimit(state, newLimit);
    // Validation above throws before anything mutates, so an invalid call
    // produces no observable cut. The change and its shrink fallout are one
    // synchronous cut; waiters are never granted early.
    state.limit = newLimit;
    if (state.isRoot) {
      state.root.poolLimit = newLimit;
    }
    refuseUnfittable(newLimit);
  }

  function updateWindowMs(newWindowMs) {
    assertInteger(newWindowMs, 'windowMs');
    if (newWindowMs <= 0) throw new RangeError('windowMs must be a positive integer');
    // The current window keeps running with a fresh, full length measured
    // from this adjustment. Used quota is not cleared, queued deadlines do
    // not move, and no request is granted early.
    state.windowMs = newWindowMs;
    clearInterval(state.timer);
    state.timer = setInterval(onWindowFire, newWindowMs);
    if (typeof state.timer.unref === 'function') state.timer.unref();
  }

  function updateMaxWaitMs(newMaxWaitMs) {
    assertInteger(newMaxWaitMs, 'maxWaitMs');
    if (newMaxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');
    // Existing waiters keep their original enqueue time; only the cap moves.
    // Waiters already past the new deadline settle as expired on the spot;
    // nothing is granted early and no deadline moves backwards into life.
    state.maxWaitMs = newMaxWaitMs;
    const t = now();
    let changed = false;
    const r = state.root;
    const q = r.queue;
    for (let i = r.head; i < q.length; i += 1) {
      const entry = q[i];
      if (entry.removed || entry.owner !== state) continue;
      const newDeadline = entry.enqueuedAt + newMaxWaitMs;
      if (newDeadline <= t) {
        settleEntry(entry, 'expired');
        changed = true;
        continue;
      }
      if (newDeadline !== entry.deadline) {
        entry.deadline = newDeadline;
        clearTimeout(entry.timer);
        armEntry(entry, newDeadline - t);
        changed = true;
      }
    }
    if (changed) recomputeMinDeadline();
  }

  function collectSubtree(target) {
    const out = new Set();
    const stack = [target];
    while (stack.length > 0) {
      const node = stack.pop();
      out.add(node);
      for (const child of node.children) stack.push(child);
    }
    return out;
  }

  function isDescendantOf(maybeDescendant, ancestor) {
    let node = maybeDescendant;
    while (node !== null) {
      if (node === ancestor) return true;
      node = node.parent;
    }
    return false;
  }

  // Rebuild the borrow side of one admitted occupation after its member moved
  // into a new family. Its own part and handle record survive; every old link
  // is detached and re-walked along the new parent chain. The bulk pool charge
  // was moved once by the caller (subtreeDraw), so links here do not move
  // poolUsed again.
  function reborrowSeg(seg, oldRootState, newRootState) {
    const m = seg.member;
    for (const link of seg.links) {
      if (link.kind === 'pool') {
        oldRootState.poolLinks.delete(link);
      } else if (link.lgen === link.lender.ownGen) {
        link.lender.lentLinks.delete(link);
        link.lender.inFlight -= link.units;
        link.lender.lentInFlight -= link.units;
      }
      if (link.mgen === m.ownGen) {
        m.inFlight -= link.units;
        m.borrowedInFlight -= link.units;
      }
    }
    seg.links = [];
    let need = seg.units - seg.own;
    let cur = m.parent;
    while (need > 0 && cur !== null) {
      if (cur === newRootState) {
        const link = {
          kind: 'pool',
          lender: newRootState,
          member: m,
          units: need,
          lgen: newRootState.poolGen,
          mgen: m.ownGen,
        };
        newRootState.poolLinks.add(link);
        seg.links.push(link);
        m.inFlight += need;
        m.borrowedInFlight += need;
        need = 0;
      } else {
        const avail = Math.max(0, cur.limit - cur.usedOwn - cur.pendingOwn - cur.pendingLends);
        const take = Math.min(need, avail);
        if (take > 0) {
          cur.usedOwn += take;
          cur.inFlight += take;
          cur.lentInFlight += take;
          const link = {
            kind: 'own',
            lender: cur,
            member: m,
            units: take,
            lgen: cur.ownGen,
            mgen: m.ownGen,
          };
          cur.lentLinks.add(link);
          seg.links.push(link);
          m.inFlight += take;
          m.borrowedInFlight += take;
          need -= take;
        }
        cur = cur.parent;
      }
    }
  }

  // Release reservation promises that referenced gates of a moved subtree.
  function releaseMovedLends(entry, moved, oldRootState) {
    if (!entry.holdsHeld) return;
    for (const seg of entry.segs) {
      if (moved.has(seg.gate) && !seg.ownReleased) {
        seg.ownReleased = true;
        seg.gate.pendingOwn -= seg.own;
        seg.gate.reserved -= seg.own;
        entry.dirty = true;
      }
      for (const link of seg.links) {
        if (!link.released && moved.has(link.lender)) {
          link.released = true;
          link.lender.pendingLends -= link.units;
          link.lender.reserved -= link.units;
          link.lender.resvAsLender.delete(entry);
          entry.dirty = true;
        }
      }
    }
  }

  // Partition the old root queue at the moved subtree boundary, then merge
  // the moved entries into the new root queue preserving global arrival
  // order (entry.seq is assigned monotonically at enqueue time).
  function migrateQueue(oldRootState, newRootState, moved) {
    const staying = [];
    const movedEntries = [];
    const straddlers = [];
    let movedLive = 0;
    const oldQ = oldRootState.queue;
    for (let i = oldRootState.head; i < oldQ.length; i += 1) {
      const entry = oldQ[i];
      if (entry.removed) continue;
      if (entry.combo) {
        let inMoved = 0;
        for (const g of entry.comboGates) if (moved.has(g)) inMoved += 1;
        if (inMoved > 0 && inMoved < entry.comboGates.length) {
          straddlers.push(entry); // split across the two families
          continue;
        }
        if (inMoved === 0) {
          staying.push(entry);
          continue;
        }
      } else if (!moved.has(entry.owner)) {
        staying.push(entry);
        continue;
      }
      // Wholly moved entry. Its old-family reservation is void: links to
      // gates outside the subtree are released too, and the entry gathers
      // anew when its turn comes in the joined family.
      if (entry.combo) {
        releaseHolds(entry);
        for (const seg of entry.segs === null ? [] : []) {
          // segs cleared by releaseHolds; nothing else to do
        }
      }
      movedEntries.push(entry);
      movedLive += 1;
    }
    // A reservation cannot span two families: refuse split combos as a whole.
    for (const entry of straddlers) settleEntry(entry, 'refused');

    // Staying combos may have borrowed own slices from gates that are leaving;
    // those promises are released here so the joined gates take clean stats.
    for (const entry of staying) {
      if (entry.combo) releaseMovedLends(entry, moved, oldRootState);
    }
    for (const entry of movedEntries) {
      if (!entry.combo) continue;
      // Moved entries were released wholesale above; drop member-set marks on
      // gates that also leave (resvAsMember moves with the gate, but the entry
      // no longer holds there).
      for (const g of entry.comboGates) {
        g.resvAsMember.delete(entry);
        g.resvAsLender.delete(entry);
      }
    }

    oldRootState.queue = staying;
    oldRootState.head = 0;
    oldRootState.liveQueued -= movedLive;
    oldRootState.minDeadline = Infinity;
    for (const entry of staying) {
      if (entry.deadline < oldRootState.minDeadline) oldRootState.minDeadline = entry.deadline;
    }

    const existing = [];
    const newQ = newRootState.queue;
    for (let i = newRootState.head; i < newQ.length; i += 1) {
      const entry = newQ[i];
      if (!entry.removed) existing.push(entry);
    }
    const merged = [];
    let a = 0;
    let b = 0;
    while (a < existing.length || b < movedEntries.length) {
      if (
        b === movedEntries.length ||
        (a < existing.length && existing[a].seq <= movedEntries[b].seq)
      ) {
        merged.push(existing[a]);
        a += 1;
      } else {
        merged.push(movedEntries[b]);
        b += 1;
      }
    }
    newRootState.queue = merged;
    newRootState.head = 0;
    newRootState.liveQueued += movedLive;
    newRootState.minDeadline = Infinity;
    for (const entry of merged) {
      if (entry.deadline < newRootState.minDeadline) newRootState.minDeadline = entry.deadline;
    }
  }

  function reparent(newParent) {
    if (
      newParent === null ||
      newParent === undefined ||
      typeof newParent !== 'object' ||
      gateState.get(newParent) === undefined
    ) {
      throw new TypeError('reparent target must be a gate created by createGate');
    }
    const newParentState = gateState.get(newParent);
    if (newParentState === state) {
      throw new RangeError('cannot reparent a gate under itself');
    }
    if (isDescendantOf(newParentState, state)) {
      throw new RangeError('cannot reparent a gate under one of its own descendants');
    }
    if (state.limit > newParentState.limit) {
      throw new RangeError('limit must not exceed the new parent limit');
    }
    // Every check above happens before any mutation: invalid reparents roll
    // back trivially and produce no cut.

    const oldRootState = state.root;
    const newRootState = newParentState.root;
    const moved = collectSubtree(state);
    let subtreeDraw = 0;
    for (const node of moved) subtreeDraw += effectiveDraw(node);

    if (oldRootState !== newRootState) {
      // Settle the borrow in the old family's window, then re-borrow from the
      // new family. Both sides of the trade are visible in one snapshot. If
      // the new pool cannot cover the draw, the whole reparent is rejected
      // with nothing changed.
      if (newRootState.poolUsed + subtreeDraw > newRootState.poolLimit) {
        throw new QuotaExceededError(
          'QUOTA_EXCEEDED',
          'cannot reparent: the new family pool cannot cover the borrowed quota',
        );
      }

      const oldDirectParent = state.parent;
      oldRootState.poolUsed -= subtreeDraw;
      newRootState.poolUsed += subtreeDraw;
      const processedSegs = new Set();
      for (const node of moved) {
        oldRootState.members.delete(node);
        newRootState.members.add(node);
        node.root = newRootState;
        node.drawGen = newRootState.poolGen; // the draw now counts in the new pool
        // Outstanding occupations keep running: rebuild their borrow links
        // against the new chain. The member's own slice and its handle stay.
        for (const rec of node.openHandles) {
          if (moved.has(rec.seg.member) && !processedSegs.has(rec.seg)) {
            processedSegs.add(rec.seg);
            reborrowSeg(rec.seg, oldRootState, newRootState);
          }
        }
      }
      // Uncommitted reservations referencing leaving gates are released for
      // staying entries as well, before the queues merge.
      for (const g of moved) {
        for (const entry of g.resvAsLender) {
          if (!moved.has(entry.owner.root)) {
            // owner root is reassigned above for moved owners; detect via queue
          }
        }
      }
      migrateQueue(oldRootState, newRootState, moved);
      // The moved waiters carry deadlines stamped by the old family clock;
      // make the joined clock at least as large so the monotonic guarantee
      // survives the move and no deadline is judged already past by accident.
      if (oldRootState.lastNow > newRootState.lastNow) {
        newRootState.lastNow = oldRootState.lastNow;
      }
      if (oldDirectParent !== null) oldDirectParent.children.delete(state);
      newParentState.children.add(state);
      state.parent = newParentState;
      if (state === oldRootState) {
        // The old root gate becomes an ordinary child: its next window fire
        // is a plain own-window flip; the new root owns the shared pool.
        state.isRoot = false;
      }
    } else {
      // Same family: only the direct link moves; the shared pool is
      // untouched, so the old direct parent sees no cut at all. Outstanding
      // lend links keep pointing at their original lenders.
      state.parent.children.delete(state);
      newParentState.children.add(state);
      state.parent = newParentState;
    }
  }

  // --- Enqueueing ------------------------------------------------------------

  function makeEntry({
    owner,
    combo,
    units,
    resolve,
    reject,
    signal,
    waitCharges,
    comboGates,
    comboUnits,
    totalUnits,
  }) {
    const t = now();
    const entry = {
      owner,
      combo,
      units,
      resolve,
      reject,
      seq: (enqueueSeq += 1),
      enqueuedAt: t,
      deadline: t + owner.maxWaitMs,
      timer: null,
      removed: false,
      signal: signal !== undefined && signal !== null ? signal : null,
      onAbort: null,
      waitCharges,
      yields: 0,
      dirty: false,
      holdsHeld: false,
      segs: null,
      comboGates: comboGates ?? null,
      comboUnits: comboUnits ?? null,
      totalUnits: totalUnits ?? units,
    };
    entry.onAbort = () => onEntryAbort(entry);
    return entry;
  }

  function enqueueEntry(r, entry) {
    if (entry.signal !== null) {
      entry.signal.addEventListener('abort', entry.onAbort, { once: true });
    }
    armEntry(entry, entry.owner.maxWaitMs);
    if (entry.deadline < r.minDeadline) r.minDeadline = entry.deadline;
    r.queue.push(entry);
  }

  function acquire(units = 1, signal) {
    assertInteger(units, 'units');
    assertSignal(signal);
    if (units < 1 || units > state.limit) {
      throw new RangeError(`units must be between 1 and ${state.limit}`);
    }
    // A signal that fired before the call settles as CANCELLED without ever
    // entering the queue or touching quota.
    if (signal !== undefined && signal !== null && signal.aborted) {
      state.cancelled += 1;
      return Promise.reject(
        new QuotaExceededError('CANCELLED', 'acquire was cancelled before it could queue'),
      );
    }
    // A non-empty queue means earlier arrivals are still owed quota; new
    // requests must not overtake them even if they would fit.
    const r = state.root;
    if (r.liveQueued === 0 && r.poolUsed + units <= r.poolLimit) {
      state.granted += 1;
      return Promise.resolve(commitSingle(state, units));
    }
    if (state.maxWaitMs === 0) {
      state.refused += 1;
      return Promise.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
    }
    state.waiting += units;
    r.liveQueued += 1;
    return new Promise((resolve, reject) => {
      const entry = makeEntry({
        owner: state,
        combo: false,
        units,
        resolve,
        reject,
        signal,
        waitCharges: [{ gate: state, units }],
      });
      enqueueEntry(r, entry);
    });
  }

  // Validate an acquireAll member list and translate public gates into the
  // internal member states. Nothing here mutates runtime state.
  function validateMembers(members) {
    if (!Array.isArray(members)) {
      throw new TypeError('members must be an array of { gate, units }');
    }
    if (members.length === 0) {
      throw new RangeError('members must contain at least one gate');
    }
    const r = state.root;
    const seen = new Set();
    const gates = [];
    const unitMap = new Map();
    let total = 0;
    for (const member of members) {
      if (member === null || typeof member !== 'object') {
        throw new TypeError('each member must be { gate, units }');
      }
      const { gate, units } = member;
      if (gate === null || typeof gate !== 'object' || gateState.get(gate) === undefined) {
        throw new TypeError('member gate must be a gate created by createGate');
      }
      const g = gateState.get(gate);
      if (typeof units !== 'number') {
        throw new TypeError('units must be a number');
      }
      if (!Number.isInteger(units) || units < 1) {
        throw new RangeError('units must be a positive integer');
      }
      if (seen.has(g)) {
        throw new RangeError('the same gate must not appear twice in one acquireAll');
      }
      if (units > g.limit) {
        throw new RangeError(`units must be between 1 and ${g.limit}`);
      }
      if (g.root !== r) {
        throw new RangeError('all member gates must belong to the same gate family');
      }
      seen.add(g);
      gates.push(g);
      unitMap.set(g, units);
      total += units;
    }
    // Grandparent/grandchild loop: one member must not sit on another's
    // ancestor chain.
    for (const g of gates) {
      let node = g.parent;
      while (node !== null) {
        if (seen.has(node)) {
          throw new RangeError('member gates must not be ancestors of one another');
        }
        node = node.parent;
      }
    }
    return { gates, unitMap, total };
  }

  function acquireAll(members, signal) {
    assertSignal(signal);
    const { gates: comboGates, unitMap: comboUnits, total: totalUnits } = validateMembers(members);
    // A signal that fired before the call settles as CANCELLED without ever
    // entering the queue or reserving anything.
    if (signal !== undefined && signal !== null && signal.aborted) {
      state.cancelled += 1;
      return Promise.reject(
        new QuotaExceededError('CANCELLED', 'acquireAll was cancelled before it could queue'),
      );
    }
    const r = state.root;

    // waiting mirrors occupation: every member carries its own slice; the
    // entry-point gate carries the whole request unless it is itself a member.
    const waitCharges = comboGates.map((g) => ({ gate: g, units: comboUnits.get(g) }));
    if (!comboGates.includes(state)) {
      waitCharges.push({ gate: state, units: totalUnits });
    }

    // No earlier arrival: reserve then commit in one synchronous cut. If the
    // pool cannot cover the whole combo, every reservation is released and the
    // attempt rolls back before the refusal/queue decision.
    if (r.liveQueued === 0) {
      const immediate = makeEntry({
        owner: state,
        combo: true,
        units: totalUnits,
        resolve: () => {},
        reject: () => {},
        signal: null,
        waitCharges: [],
        comboGates,
        comboUnits,
        totalUnits,
      });
      const segs = buildSegs(comboGates, (g) => comboUnits.get(g));
      gatherHolds(immediate, segs);
      if (r.poolUsed + totalUnits <= r.poolLimit) {
        state.granted += 1;
        return Promise.resolve(commitCombo(immediate));
      }
      releaseHolds(immediate);
      state.rolledBack += 1;
      if (state.maxWaitMs === 0) {
        state.refused += 1;
        return Promise.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
      }
    } else if (state.maxWaitMs === 0) {
      state.refused += 1;
      return Promise.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
    }

    for (const charge of waitCharges) charge.gate.waiting += charge.units;
    r.liveQueued += 1;
    return new Promise((resolve, reject) => {
      const entry = makeEntry({
        owner: state,
        combo: true,
        units: totalUnits,
        resolve,
        reject,
        signal,
        waitCharges,
        comboGates,
        comboUnits,
        totalUnits,
      });
      enqueueEntry(r, entry);
      // Reserve member slices and ancestor lends up front; the pool
      // shortfall is promised at the combo's turn. The hold makes `reserved`
      // observable while the combo waits and is fully released on rollback.
      gatherHolds(entry, buildSegs(comboGates, (g) => comboUnits.get(g)));
    });
  }

  function stats() {
    return {
      limit: state.limit,
      windowMs: state.windowMs,
      inFlight: state.inFlight,
      waiting: state.waiting,
      granted: state.granted,
      refused: state.refused,
      expired: state.expired,
      cancelled: state.cancelled,
      reserved: state.reserved,
      rolledBack: state.rolledBack,
    };
  }

  const gate = { acquire, acquireAll, stats, updateLimit, updateWindowMs, updateMaxWaitMs, reparent };
  gateState.set(gate, state);
  return gate;
}

