// combo that cannot be gathered whole does not starve later arrivals: a
// later request that fits outright passes it and the combo yields once;
// after yielding twice it becomes a hard barrier like a non-fitting single.
// The pass is linear in the live queue: blocked combos form a small list
// touched once per later served request, amortized by queue compaction.
function allocate() {
  const r = state.root;
  const q = r.queue;
  const blocked = []; // soft-blocked combos crossed, arrival order
  let hardBlocked = 0; // blocked combos already at the two-yield cap
  for (let i = r.head; i < q.length; i += 1) {
    const entry = q[i];
    if (entry.removed) continue;
    if (hardBlocked > 0) break;
