    } else {
      // Any step short: the plan touched nothing; count one whole rollback
      // (no other counter moves) and become a soft barrier. At two yields
      // the barrier hardens and the pass stops right after it.
      entry.owner.rolledBack += 1;
      blocked.push(entry);
      if (entry.yields >= 2) break;
    }
